#!/usr/bin/env python3
from pathlib import Path

DEEP = Path('omega/plugin.video.umbrella/resources/lib/debrid/deepbrid.py')
ROUTER = Path('omega/plugin.video.umbrella/resources/lib/modules/router.py')

deep = DEEP.read_text(encoding='utf-8')
router = ROUTER.read_text(encoding='utf-8')

old_add = '''    def _add_cloud_file_item(\n        self,\n        syshandle,\n        count,\n        name,\n        direct,\n        size_text=''\n    ):\n        if not direct:\n            return\n\n        label = '%02d | [B]FILE[/B]' % count\n        if size_text:\n            label += ' | %s' % size_text\n        label += ' | %s' % name\n\n        listitem = control.item(label=label, offscreen=True)\n        self._cloud_listitem_art(listitem)\n        control.set_info(\n            listitem,\n            {\n                'title': name,\n                'plot': ('Size: %s' % size_text) if size_text else name\n            }\n        )\n        listitem.setProperty('IsPlayable', 'true')\n        item_url = (\n            'plugin://plugin.video.umbrella/?action=db_PlayDownload&url=%s' %\n            quote_plus(direct)\n        )\n        control.addItem(\n            handle=syshandle,\n            url=item_url,\n            listitem=listitem,\n            isFolder=False\n        )\n'''

new_add = '''    def _add_cloud_file_item(\n        self,\n        syshandle,\n        count,\n        name,\n        stable_token,\n        size_text=''\n    ):\n        if not stable_token:\n            return\n\n        label = '%02d | [B]FILE[/B]' % count\n        if size_text:\n            label += ' | %s' % size_text\n        label += ' | %s' % name\n\n        listitem = control.item(label=label, offscreen=True)\n        self._cloud_listitem_art(listitem)\n        control.set_info(\n            listitem,\n            {\n                'title': name,\n                'plot': ('Size: %s' % size_text) if size_text else name\n            }\n        )\n        listitem.setProperty('IsPlayable', 'true')\n        item_url = (\n            'plugin://plugin.video.umbrella/?action=db_PlayCloud&token=%s' %\n            quote_plus(stable_token)\n        )\n        control.addItem(\n            handle=syshandle,\n            url=item_url,\n            listitem=listitem,\n            isFolder=False\n        )\n'''

old_browse = '''    def browse_user_torrents(\n        self,\n        folder_id,\n        mediatype='torrent'\n    ):\n        try:\n            syshandle = int(argv[1])\n        except Exception:\n            return\n\n        if mediatype == 'usenet':\n            info = self.usenet_info(folder_id)\n            files = info.get('files') or [] if isinstance(info, dict) else []\n            count = 0\n\n            for item in files:\n                if not isinstance(item, dict):\n                    continue\n                name = item.get('name') or item.get('filename') or ''\n                direct = item.get('link') or ''\n                if not direct or not self._is_video_link(direct, name):\n                    continue\n                count += 1\n                size_text = item.get('size_human') or ''\n                if not size_text and item.get('size'):\n                    try:\n                        size_text = '%.2f GB' % (\n                            float(item.get('size')) / 1073741824.0\n                        )\n                    except Exception:\n                        size_text = str(item.get('size'))\n                self._add_cloud_file_item(\n                    syshandle,\n                    count,\n                    name or 'Usenet file %s' % count,\n                    direct,\n                    size_text=size_text\n                )\n\n        else:\n            info = self.torrent_info(folder_id)\n            if not isinstance(info, dict):\n                info = {}\n            links = info.get('links') or []\n            probes = self._probe_torrent_link_names(links)\n\n            if len(links) == 1 and probes and not probes[0].get('filename'):\n                probes[0]['filename'] = info.get('filename') or 'Torrent file'\n\n            fresh_info = self.torrent_info(folder_id)\n            fresh_links = (\n                fresh_info.get('links') or []\n                if isinstance(fresh_info, dict)\n                else []\n            )\n\n            if len(fresh_links) != len(links):\n                control.notification(\n                    title=self.name,\n                    message='Torrent links changed; reopen this folder',\n                    icon='WARNING'\n                )\n                control.directory(syshandle, cacheToDisc=False)\n                return\n\n            count = 0\n            for probe in probes:\n                index = probe.get('index')\n                if index is None or index >= len(fresh_links):\n                    continue\n                name = probe.get('filename') or ''\n                if not self._is_video_link('', name):\n                    continue\n                count += 1\n                self._add_cloud_file_item(\n                    syshandle,\n                    count,\n                    name,\n                    fresh_links[index]\n                )\n\n        control.content(syshandle, 'files')\n        control.directory(syshandle, cacheToDisc=False)\n'''

new_browse = '''    def browse_user_torrents(\n        self,\n        folder_id,\n        mediatype='torrent'\n    ):\n        try:\n            syshandle = int(argv[1])\n        except Exception:\n            return\n\n        if mediatype == 'usenet':\n            info = self.usenet_info(folder_id)\n            files = info.get('files') or [] if isinstance(info, dict) else []\n            expected_count = len(files)\n            count = 0\n\n            for index, item in enumerate(files):\n                if not isinstance(item, dict):\n                    continue\n                name = item.get('name') or item.get('filename') or ''\n                direct = item.get('link') or ''\n                if not direct or not self._is_video_link(direct, name):\n                    continue\n                count += 1\n                size_text = item.get('size_human') or ''\n                if not size_text and item.get('size'):\n                    try:\n                        size_text = '%.2f GB' % (\n                            float(item.get('size')) / 1073741824.0\n                        )\n                    except Exception:\n                        size_text = str(item.get('size'))\n                stable_token = 'dbu,%s,%s,%s' % (\n                    folder_id,\n                    index,\n                    expected_count\n                )\n                self._add_cloud_file_item(\n                    syshandle,\n                    count,\n                    name or 'Usenet file %s' % count,\n                    stable_token,\n                    size_text=size_text\n                )\n\n        else:\n            info = self.torrent_info(folder_id)\n            if not isinstance(info, dict):\n                info = {}\n            links = info.get('links') or []\n            expected_count = len(links)\n            probes = self._probe_torrent_link_names(links)\n\n            if len(links) == 1 and probes and not probes[0].get('filename'):\n                probes[0]['filename'] = info.get('filename') or 'Torrent file'\n\n            count = 0\n            for probe in probes:\n                index = probe.get('index')\n                if index is None or index >= expected_count:\n                    continue\n                name = probe.get('filename') or ''\n                if not self._is_video_link('', name):\n                    continue\n                count += 1\n                stable_token = 'dbt,%s,%s,%s' % (\n                    folder_id,\n                    index,\n                    expected_count\n                )\n                self._add_cloud_file_item(\n                    syshandle,\n                    count,\n                    name,\n                    stable_token\n                )\n\n        control.content(syshandle, 'files')\n        control.directory(syshandle, cacheToDisc=False)\n'''

for old, new, label in ((old_add, new_add, '_add_cloud_file_item'), (old_browse, new_browse, 'browse_user_torrents')):
    count = deep.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected exactly one block, found {count}')
    deep = deep.replace(old, new, 1)

old_router = """\t\telif action == 'db_PlayDownload':\n\t\t\tif url:\n\t\t\t\tcontrol.player.play(url.replace(' ', '%20'))\n"""
new_router = """\t\telif action == 'db_PlayCloud':\n\t\t\ttoken = params.get('token') or ''\n\t\t\tresolved = None\n\t\t\ttry:\n\t\t\t\tkind, request_id, index, expected_count = token.split(',', 3)\n\t\t\t\tfrom resources.lib.debrid.deepbrid import Deepbrid\n\t\t\t\tdb = Deepbrid()\n\t\t\t\tif kind == 'dbt':\n\t\t\t\t\tresolved = db.resolve_cloud_torrent_file(\n\t\t\t\t\t\trequest_id, index, expected_count\n\t\t\t\t\t)\n\t\t\t\telif kind == 'dbu':\n\t\t\t\t\tresolved = db.resolve_cloud_usenet_file(\n\t\t\t\t\t\trequest_id, index, expected_count\n\t\t\t\t\t)\n\t\t\texcept Exception:\n\t\t\t\tfrom resources.lib.modules import log_utils\n\t\t\t\tlog_utils.error('Deepbrid manual cloud resolve: ')\n\n\t\t\tif resolved:\n\t\t\t\tcontrol.player.play(resolved.replace(' ', '%20'))\n\t\t\telse:\n\t\t\t\tcontrol.notification(\n\t\t\t\t\ttitle='Deepbrid',\n\t\t\t\t\tmessage='Cloud file could not be refreshed',\n\t\t\t\t\ticon='ERROR'\n\t\t\t\t)\n\t\telif action == 'db_PlayDownload':\n\t\t\tif url:\n\t\t\t\tcontrol.player.play(url.replace(' ', '%20'))\n"""
count = router.count(old_router)
if count != 1:
    raise SystemExit(f'router db_PlayDownload block: expected 1, found {count}')
router = router.replace(old_router, new_router, 1)

DEEP.write_text(deep, encoding='utf-8')
ROUTER.write_text(router, encoding='utf-8')
